mapper.select:
SELECT id, normalized_email, display_name, created_at
FROM iam_identities
WHERE normalized_email = #{normalizedEmail}

WITH invalidated_initial AS (
    UPDATE iam_credentials
    SET invalidated_at = #{password.issuedAt}
    WHERE id = #{initialCredentialId}
      AND identity_id = #{password.identityId}
      AND credential_type = 'INITIAL_PLATFORM_PASSWORD'
      AND invalidated_at IS NULL
    RETURNING id
)
INSERT INTO iam_credentials (identity_id, credential_type, password_hash, issued_at, expires_at, invalidated_at)
SELECT #{password.identityId}, #{password.credentialType}, #{password.passwordHash}, #{password.issuedAt},
       #{password.expiresAt}, #{password.invalidatedAt}
WHERE EXISTS (SELECT 1 FROM invalidated_initial)
RETURNING id, identity_id, credential_type, password_hash, issued_at, expires_at, invalidated_at

mapper.update:
UPDATE iam_credentials
SET invalidated_at = #{invalidatedAt}
WHERE id = #{credentialId} AND invalidated_at IS NULL
